console.log(["1", "2", "3"].map(parseInt)); // -> [1, NaN, NaN]
// map wywoluje callback z (element, indeks, tablica) - parseInt bierze indeks jako podstawe systemu.

function zadanie(nazwa) {
  return "wykonano " + nazwa;
}

const zadania = [zadanie.bind(null, "a"), zadanie.bind(null, "b")];
console.log(zadania.map(f => f())); // -> ["wykonano a", "wykonano b"]

function pomnoz(a, b) {
  return a * b;
}

function stworzMnoznik(n) {
  return pomnoz.bind(null, n);
}

const razy2 = stworzMnoznik(2);
const razy10 = stworzMnoznik(10);

console.log(razy2(4));  // -> 8
console.log(razy10(4)); // -> 40

const dodaj = (a, b) => a + b;
const dodaj5 = dodaj.bind({ ignorowane: true }, 5);

console.log(dodaj5(1)); // -> 6
// thisArg zostal zignorowany (strzalka ma this leksykalne), ale pierwszy argument zostal ustawiony z gory.

function loguj(poziom, tekst) {
  return "[" + poziom + "] " + this.nazwa + ": " + tekst;
}

const info = loguj.bind({ nazwa: "app" }, "info");
console.log(info("start"));  // -> "[info] app: start"
console.log(info("koniec")); // -> "[info] app: koniec"

function opisz(a, b) {
  return this.n + a + b;
}
const o = { n: 1 };

console.log(opisz.call(o, 2, 3));       // -> 6 (wywoluje od razu, argumenty po przecinku)
console.log(opisz.apply(o, [2, 3]));    // -> 6 (wywoluje od razu, argumenty w tablicy)
const zwiazana = opisz.bind(o, 2);
console.log(zwiazana(3));               // -> 6 (najpierw zwraca funkcje, wywolujemy ja pozniej)

